"""Generate the v3 ACQUISITION training sets.

Additive and non-destructive: writes only under `data/acquisition/`. The frozen
`data/train/`, `data/common/` and the sealed `policy_test` are never rewritten.

Design invariants, all asserted at build time:
  * contexts and target policies are regenerated BYTE-IDENTICALLY from
    configs/design.yaml + the recorded scenario pool (so policy_test stays valid);
  * labels are deterministic  (label_letter == target_letter, always);
  * every new option pair is canonically disjoint from EVERY existing split,
    including the sealed policy_test - which is read for its `pair_hash` column
    ONLY, never for prompts, keys, targets or model performance;
  * A/B target balance and AB/BA order balance are exact (or off by at most one
    row per context x adapter) and are achieved WITHOUT rejecting any drawn pair,
    so the utility-margin distribution is not selected on;
  * A1 and A2 draw independent training pairs even where their policies are
    identical (shared-overlap contexts).
"""
import csv, json
from pathlib import Path

import yaml

from .seeds import stream
from .scenarios import load_pool, select_contexts
from .design import build_design
from .policies import build_policies, utility
from .trials import draw_pairs, target_letter, positioned
from .render import render_messages
from .provenance import sha256_file, env_record

ROOT = Path(__file__).resolve().parents[2]
CFG, DATA = ROOT / "configs", ROOT / "data"

# The sealed split is opened for this ONE column and nothing else.
SEALED_HASH_ONLY = ("policy_test",)


def existing_hashes():
    """Canonical pair hashes already committed to ANY split, per context.

    policy_test contributes `pair_hash` only. No prompt, key, target letter or
    utility is read from it, and nothing about it is reported.
    """
    used, prov = {}, {}
    for p in sorted((DATA / "train").glob("*/train_full.jsonl")):
        n = 0
        for line in open(p):
            r = json.loads(line)
            used.setdefault(r["context_id"], set()).add(r["pair_hash"]); n += 1
        prov[str(p.relative_to(ROOT))] = n
    for split in ("policy_val", "self_pred", "relational"):
        f = DATA / "common" / f"{split}_prompts.jsonl"
        n = 0
        for line in open(f):
            r = json.loads(line)
            used.setdefault(r["context_id"], set()).add(r["pair_hash"]); n += 1
        prov[str(f.relative_to(ROOT))] = n
    for split in SEALED_HASH_ONLY:
        f = DATA / "common" / f"{split}_prompts.jsonl"
        if not f.exists():
            raise FileNotFoundError(f"{f} missing; cannot prove disjointness from the sealed split")
        n = 0
        for line in open(f):
            r = json.loads(line)          # pair_hash + context_id only
            used.setdefault(r["context_id"], set()).add(r["pair_hash"]); n += 1
        prov[str(f.relative_to(ROOT)) + " (pair_hash only)"] = n
    return used, prov


def assign_orders(rng, pairs, attrs, w, n):
    """Winner-stratified exact order assignment.

    Let n0 = #pairs whose option_0 the policy prefers, n1 = n - n0. Give
    a = n0 // 2 of the option_0-winners order AB (target 'A') and the rest BA
    (target 'B'); give b = n//2 - a of the option_1-winners order AB (target
    'B') and the rest BA (target 'A'). Then
        #target A = a + (n1 - b)   and   #order AB = a + b
    are both exactly n/2 when n0 is even. Selection WITHIN a winner group is
    uniform, and no pair is discarded, so the utility-margin distribution is
    untouched.
    """
    win0, win1 = [], []
    for i, p in enumerate(pairs):
        u0 = utility(p["option_0"], attrs, w)
        u1 = utility(p["option_1"], attrs, w)
        (win0 if u0 > u1 else win1).append(i)
    n0 = len(win0)
    a = n0 // 2
    b = n // 2 - a
    b = max(0, min(b, len(win1)))
    ab0 = set(rng.choice(win0, size=a, replace=False).tolist()) if a else set()
    ab1 = set(rng.choice(win1, size=b, replace=False).tolist()) if b else set()
    ab = ab0 | ab1
    orders = ["AB" if i in ab else "BA" for i in range(n)]
    return orders, {"n_option0_winners": n0, "n_option1_winners": len(win1),
                    "a_option0_shown_AB": a, "b_option1_shown_AB": b,
                    "n0_even": n0 % 2 == 0}


def build():
    acq = yaml.safe_load((CFG / "acquisition.yaml").read_text())
    d = yaml.safe_load((CFG / "design.yaml").read_text())
    dd = yaml.safe_load((CFG / "data.yaml").read_text())
    pc = yaml.safe_load((CFG / "prompt.yaml").read_text())
    seed = d["master_seed"]
    n = int(acq["train_pairs_per_context"])
    adapters = list(acq["adapters"])
    assert acq["deterministic_labels"] and float(acq["weak_context_flip_fraction"]) == 0.0

    pool_path = ROOT / acq["scenario_pool"]
    got = sha256_file(pool_path)
    if got != acq["scenario_pool_sha256"]:
        raise RuntimeError(f"scenario pool hash mismatch: {got} != {acq['scenario_pool_sha256']}")

    _, usable = load_pool(pool_path)
    contexts = select_contexts(usable, seed, d["n_contexts"])
    contexts, _ = build_design(seed, contexts, d["cells_per_condition"],
                               d["max_consecutive_run"])
    policies, _ = build_policies(seed, contexts, d["adapters"], d["n_attributes"],
                                 max_abs_cos=float(d["max_abs_cos_nonshared"]),
                                 max_attempts=int(d["policy_max_redraw_attempts"]))

    # PROOF that contexts/policies are unchanged -> the sealed policy_test stays valid.
    def norm(s): return s.replace("\r\n", "\n").rstrip("\n")
    chk = {}
    import io
    b = io.StringIO(); w_ = csv.writer(b)
    w_.writerow(["adapter_id", "context_id", "overlap_status", "assigned_consistency"]
                + [f"w{i+1}" for i in range(5)])
    for a in d["adapters"]:
        for c in contexts:
            ov = c["overlap_A"] if a.startswith("A") else c["overlap_B"]
            w_.writerow([a, c["context_id"], ov, c["assigned_consistency"]]
                        + policies[a][c["context_id"]])
    chk["target_policies_unchanged"] = norm(b.getvalue()) == norm((DATA/"design"/"target_policies.csv").read_text())
    if not chk["target_policies_unchanged"]:
        raise RuntimeError("target policies changed; the sealed policy_test would be invalidated")

    used, hash_prov = existing_hashes()
    tol = float(dd["tie_rel_tolerance"])
    rows = {a: [] for a in adapters}
    order_meta = {}

    for a in adapters:
        for c in contexts:
            cid, attrs = c["context_id"], c["attributes"]
            w = policies[a][cid]
            rng = stream(seed, f"acq3|examples|{a}|{cid}|train")
            pairs, ties = draw_pairs(rng, attrs, cid, n, [w], tol,
                                     dd["max_resample_attempts"], used[cid])
            orng = stream(seed, f"acq3|orders|{a}|{cid}|train")
            orders, meta = assign_orders(orng, pairs, attrs, w, n)
            meta["ties_resampled"] = ties
            order_meta[f"{a}|{cid}"] = meta
            for i, (p, order) in enumerate(zip(pairs, orders)):
                tl, uA, uB = target_letter(p, attrs, w, order)
                vA, vB, iA, iB = positioned(p, order)
                rows[a].append({
                    "row_id": f"acq|{a}|{cid}|{i:04d}|{order}",
                    "adapter_id": a, "context_id": cid,
                    "scenario_name": c["scenario_name"], "split": "acquisition_train",
                    "instance_id": i, "pair_hash": p["pair_hash"],
                    "presentation_order": order,
                    "option_A_values": vA, "option_B_values": vB,
                    "underlying_at_A": iA, "underlying_at_B": iB,
                    "target_letter": tl, "label_letter": tl,      # DETERMINISTIC
                    "label_follows_target": True,
                    "utility_A": uA, "utility_B": uB,
                    "utility_margin": abs(uA - uB),
                    "overlap_A": c["overlap_A"], "overlap_B": c["overlap_B"],
                    "target_w": w,
                    "messages": render_messages(cid, c["question"], attrs, vA, vB,
                                                pc, label_letter=tl),
                })

    out = ROOT / acq["output_dir"]
    written = []
    for a in adapters:
        full = out / "train" / a / "train_full.jsonl"
        sft = out / "train" / a / "train_sft.jsonl"
        full.parent.mkdir(parents=True, exist_ok=True)
        with open(full, "w") as f:
            for r in rows[a]:
                f.write(json.dumps(r, sort_keys=True) + "\n")
        with open(sft, "w") as f:
            for r in rows[a]:
                f.write(json.dumps({"messages": r["messages"]}, sort_keys=True) + "\n")
        written += [full, sft]

    man = {
        "version": 3, "status": "ACTIVE", "family": "acquisition",
        "generated_by": env_record(), "master_seed": seed,
        "derived_from": {"design_config": sha256_file(CFG/"design.yaml"),
                         "prompt_config": sha256_file(CFG/"prompt.yaml"),
                         "acquisition_config": sha256_file(CFG/"acquisition.yaml"),
                         "scenario_pool_sha256": got},
        "invariants": chk,
        "train_pairs_per_context": n, "adapters": adapters,
        "n_examples_per_adapter": {a: len(rows[a]) for a in adapters},
        "disjointness_sources": hash_prov,
        "order_assignment": {"scheme": acq["order_assignment"], "per_cell": order_meta},
        "files": {str(p.relative_to(ROOT)): sha256_file(p) for p in written},
    }
    (out / "acquisition_manifest.json").parent.mkdir(parents=True, exist_ok=True)
    (out / "acquisition_manifest.json").write_text(json.dumps(man, indent=2, default=str))
    return rows, man


if __name__ == "__main__":
    _, m = build()
    print(json.dumps({k: v for k, v in m.items()
                      if k in ("version","invariants","n_examples_per_adapter",
                               "train_pairs_per_context","disjointness_sources")}, indent=2))
